local reliable = remotes:WaitForChild("EXAMPLE1_RELIABLE")
assert(reliable:IsA("RemoteEvent"), "Expected EXAMPLE1_RELIABLE to be a RemoteEvent")

export type MatchStateData = ({
	["MatchId"]: (string),
	["CurrentPhase"]: (string),
	["TimeElapsedMiliseconds"]: (number),
	["IsClockRunning"]: (boolean),
	["Scores"]: ({ (number) }),
	["CurrentHalf"]: (number),
})
export type BallData = ({
	["BallSpeedVector"]: (vector),
	["BallRotationVector"]: (vector),
	["BallCurrentPosition"]: (vector),
	["Ball150Prediction"]: (vector),
})

local function sendEvents()
	if outgoing_used ~= 0 then
		local buff = buffer.create(outgoing_used)
		buffer.copy(buff, 0, outgoing_buff, 0, outgoing_used)

		reliable:FireServer(buff, outgoing_inst)

		outgoing_buff = buffer.create(64)
		outgoing_used = 0
		outgoing_size = 64
		table.clear(outgoing_inst)
	end
end

RunService.Heartbeat:Connect(sendEvents)

local reliable_events = table.create(4)
local reliable_event_queue: { [number]: { any } } = table.create(4)
