			value["CurrentPhase"] = buffer.readstring(incoming_buff, read(len_2), len_2)
			assert(utf8.len(value["CurrentPhase"]) ~= nil, "value is not valid utf-8")
			value["TimeElapsedMiliseconds"] = buffer.readu16(incoming_buff, read(2))
			value["IsClockRunning"] = bit32.btest(bool_1, 0b0000000000000001)
			local len_3 = buffer.readu16(incoming_buff, read(2))
			assert(len_3 >= 1, "value is less than 1!")
			value["Scores"] = table.create(len_3)
			for i_1 = 1, len_3 do
